package com.nequard.offline;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="local_services") public class LocalService{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)String name;@Column(name="organization_id",nullable=false)UUID organizationId;String category,endpoint,status="AVAILABLE";boolean syncEnabled=true;
public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public boolean isSyncEnabled(){return syncEnabled;}public void setSyncEnabled(boolean v){syncEnabled=v;}}